(1, '{\"en\":\"Necess\\u00e1rio\"}', 'necessary', '{\"en\":\"<p>Os cookies necess\\u00e1rios s\\u00e3o necess\\u00e1rios para ativar os recursos b\\u00e1sicos deste site, como fornecer login seguro ou ajustar suas prefer\\u00eancias de consentimento. Estes cookies n\\u00e3o armazenam quaisquer dados de identifica\\u00e7\\u00e3o pessoal.<\\/p>\"}', 1, 1, 0, 1, '[]', '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(2, '{\"en\":\"Funcional\"}', 'functional', '{\"en\":\"<p>Os cookies necess\\u00e1rios s\\u00e3o necess\\u00e1rios para ativar os recursos b\\u00e1sicos deste site, como fornecer login seguro ou ajustar suas prefer\\u00eancias de consentimento. Estes cookies n\\u00e3o armazenam quaisquer dados de identifica\\u00e7\\u00e3o pessoal.<\\/p>\"}', 0, 1, 0, 1, '[]', '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(3, '{\"en\":\"Analiticos\"}', 'analytics', '{\"en\":\"<p>Os cookies anal\\u00edticos s\\u00e3o utilizados para compreender como os visitantes interagem com o site. Esses cookies ajudam a fornecer informa\\u00e7\\u00f5es sobre m\\u00e9tricas como n\\u00famero de visitantes, taxa de rejei\\u00e7\\u00e3o, origem do tr\\u00e1fego, etc.<\\/p>\"}', 0, 1, 0, 1, '[]', '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(4, '{\"en\":\"Performance\"}', 'performance', '{\"en\":\"<p>Os cookies de desempenho s\\u00e3o usados \\u200b\\u200bpara compreender e analisar os principais \\u00edndices de desempenho do site, o que ajuda a oferecer uma melhor experi\\u00eancia de usu\\u00e1rio aos visitantes.<\\/p>\"}', 0, 1, 0, 1, '[]', '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(5, '{\"en\":\"An\\u00fancio\"}', 'advertisement', '{\"en\":\"<p>Os cookies publicit\\u00e1rios s\\u00e3o utilizados para fornecer aos visitantes an\\u00fancios personalizados com base nas p\\u00e1ginas que visitou anteriormente e para analisar a efic\\u00e1cia das campanhas publicit\\u00e1rias.<\\/p>\"}', 0, 1, 0, 1, '[]', '0000-00-00 00:00:00', '0000-00-00 00:00:00');
INSERT INTO `wp_comments` (`comment_ID`, `comment_post_ID`, `comment_author`, `comment_author_email`, `comment_author_url`, `comment_author_IP`, `comment_date`, `comment_date_gmt`, `comment_content`, `comment_karma`, `comment_approved`, `comment_agent`, `comment_type`, `comment_parent`, `user_id`) VALUES
(1, 1, 'Um comentarista do WordPress', 'wapuu@wordpress.example', 'https://br.wordpress.org/', '', '2026-03-21 12:35:49', '2026-03-21 15:35:49', 'Oi, isto é um comentário.\nPara iniciar a moderar, editar e excluir comentários, visite a tela Comentários no painel.\nOs avatares dos comentaristas vêm do <a href=\"https://br.gravatar.com/\">Gravatar</a>.', 0, '1', '', 'comment', 0, 0);
