(25, 1, '2026-03-22 22:57:34', '2026-03-23 01:57:34', '<!-- wp:gallery {\"linkTo\":\"none\"} -->\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped\"><!-- wp:image {\"sizeSlug\":\"large\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"https://unsplash.com/pt-br/fotografias/homem-na-jaqueta-preta-e-jeans-jeans-azuis-que-montam-a-motocicleta-UZUzvJEvKnI\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img/></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery -->', '', '', 'trash', 'closed', 'closed', '', '__trashed', '', '', '2026-03-22 22:57:34', '2026-03-23 01:57:34', '', 0, 'http://localhost/wordpress/?page_id=25', 0, 'page', '', 0),
